impl Solution{pub fn odd_even_list(head:Option<Box<ListNode>>)->Option<Box<ListNode>>{let mut vals=vec![];let mut p=head;while let Some(mut n)=p{vals.push(n.val);p=n.next.take();}let mut out=vec![];for i in (0..vals.len()).step_by(2){out.push(vals[i])}for i in (1..vals.len()).step_by(2){out.push(vals[i])}let mut r=None;for &v in out.iter().rev(){let mut n=Box::new(ListNode::new(v));n.next=r;r=Some(n);}r}}
